// app.js
const api = require('./utils/api.js')
const auth = require('./utils/auth.js')

App({
  globalData: {
    userInfo: null,
    profile: null,
    token: null,
    isLogin: false,
    systemInfo: null,
    currentLocation: null,
    unreadCount: 0,
    matchedUsers: [],
    likedUsers: [],
    visitedUsers: []
  },

  onLaunch: function(options) {
    console.log('小程序启动', options)

    // 获取系统信息
    this.getSystemInfo()

    // 检查登录状态
    this.checkLoginStatus()

    // 初始化位置服务
    this.initLocation()

    // 检查更新
    this.checkUpdate()
  },

  onShow: function(options) {
    console.log('小程序显示', options)

    // 检查消息提醒权限
    this.checkNotificationAuth()

    // 刷新未读消息数
    if (this.globalData.isLogin) {
      this.refreshUnreadCount()
    }
  },

  onHide: function() {
    console.log('小程序隐藏')
  },

  onError: function(msg) {
    console.error('小程序错误:', msg)
    // 错误上报
    this.reportError(msg)
  },

  // 获取系统信息
  getSystemInfo() {
    wx.getSystemInfo({
      success: (res) => {
        this.globalData.systemInfo = res
        console.log('系统信息:', res)
      }
    })
  },

  // 检查登录状态
  checkLoginStatus() {
    const token = wx.getStorageSync('token')
    const userInfo = wx.getStorageSync('userInfo')

    if (token && userInfo) {
      this.globalData.token = token
      this.globalData.userInfo = userInfo
      this.globalData.isLogin = true

      // 验证token有效性
      this.validateToken()
    }
  },

  // 验证token
  async validateToken() {
    try {
      const res = await api.validateToken()
      if (res.code === 200) {
        this.globalData.profile = res.data.profile
      } else {
        this.logout()
      }
    } catch (error) {
      console.error('验证token失败:', error)
      this.logout()
    }
  },

  // 初始化位置
  initLocation() {
    wx.getLocation({
      type: 'gcj02',
      success: (res) => {
        this.globalData.currentLocation = {
          latitude: res.latitude,
          longitude: res.longitude
        }
        console.log('获取位置成功:', res)
      },
      fail: (error) => {
        console.log('获取位置失败:', error)
        // 引导用户开启位置权限
        this.showLocationAuth()
      }
    })
  },

  // 位置权限引导
  showLocationAuth() {
    wx.showModal({
      title: '位置权限',
      content: '为了给您推荐附近的用户，需要获取您的位置信息',
      confirmText: '去设置',
      success: (res) => {
        if (res.confirm) {
          wx.openSetting({
            success: (authRes) => {
              if (authRes.authSetting['scope.userLocation']) {
                this.initLocation()
              }
            }
          })
        }
      }
    })
  },

  // 检查更新
  checkUpdate() {
    if (wx.canIUse('getUpdateManager')) {
      const updateManager = wx.getUpdateManager()

      updateManager.onCheckForUpdate((res) => {
        if (res.hasUpdate) {
          updateManager.onUpdateReady(() => {
            wx.showModal({
              title: '发现新版本',
              content: '新版本已准备好，是否重启应用？',
              success: (modalRes) => {
                if (modalRes.confirm) {
                  updateManager.applyUpdate()
                }
              }
            })
          })

          updateManager.onUpdateFailed(() => {
            wx.showToast({
              title: '更新失败',
              icon: 'error'
            })
          })
        }
      })
    }
  },

  // 检查通知权限
  checkNotificationAuth() {
    wx.getSetting({
      withSubscriptions: true,
      success: (res) => {
        if (!res.subscriptionsSetting.mainSwitch) {
          // 引导开启订阅消息
          this.showSubscribeModal()
        }
      }
    })
  },

  // 订阅消息引导
  showSubscribeModal() {
    wx.showModal({
      title: '消息提醒',
      content: '开启消息提醒，及时了解匹配和聊天消息',
      confirmText: '开启',
      success: (res) => {
        if (res.confirm) {
          wx.openSetting({
            withSubscriptions: true
          })
        }
      }
    })
  },

  // 刷新未读消息数
  async refreshUnreadCount() {
    try {
      const res = await api.getUnreadCount()
      if (res.code === 200) {
        this.globalData.unreadCount = res.data.count
        // 更新tabbar badge
        if (res.data.count > 0) {
          wx.setTabBarBadge({
            index: 2,
            text: res.data.count > 99 ? '99+' : res.data.count.toString()
          })
        } else {
          wx.removeTabBarBadge({
            index: 2
          })
        }
      }
    } catch (error) {
      console.error('获取未读消息数失败:', error)
    }
  },

  // 登出
  logout() {
    this.globalData.userInfo = null
    this.globalData.profile = null
    this.globalData.token = null
    this.globalData.isLogin = false

    wx.removeStorageSync('token')
    wx.removeStorageSync('userInfo')
    wx.removeTabBarBadge({index: 2})

    // 跳转到登录页
    wx.reLaunch({
      url: '/pages/login/login'
    })
  },

  // 错误上报
  reportError(msg) {
    // 这里可以接入错误监控服务
    console.error('上报错误:', msg)
  },

  // 更新用户信息
  updateUserInfo(userInfo) {
    this.globalData.userInfo = userInfo
    wx.setStorageSync('userInfo', userInfo)
  },

  // 更新个人资料
  updateProfile(profile) {
    this.globalData.profile = profile
  },

  // 工具方法：获取用户信息
  getUserInfo() {
    return this.globalData.userInfo
  },

  // 工具方法：获取用户资料
  getProfile() {
    return this.globalData.profile
  },

  // 工具方法：检查是否登录
  isLogin() {
    return this.globalData.isLogin
  }
})

