// utils/api.js - API请求封装

const app = getApp()

// API基础配置
const config = {
  baseUrl: 'https://api.dating-app.com', // 替换为实际API地址
  timeout: 10000,
  retryTimes: 3
}

// HTTP状态码
const STATUS_CODE = {
  SUCCESS: 200,
  UNAUTHORIZED: 401,
  FORBIDDEN: 403,
  NOT_FOUND: 404,
  SERVER_ERROR: 500
}

/**
 * 发起网络请求
 * @param {Object} options 请求选项
 */
function request(options) {
  const {
    url,
    method = 'GET',
    data = {},
    header = {},
    loading = true,
    showError = true
  } = options

  // 显示加载提示
  if (loading) {
    wx.showLoading({
      title: '加载中...',
      mask: true
    })
  }

  return new Promise((resolve, reject) => {
    // 构建请求头
    const requestHeader = {
      'Content-Type': 'application/json',
      ...header
    }

    // 添加token
    const token = app.globalData.token || wx.getStorageSync('token')
    if (token) {
      requestHeader.Authorization = `Bearer ${token}`
    }

    wx.request({
      url: config.baseUrl + url,
      method,
      data,
      header: requestHeader,
      timeout: config.timeout,
      success: (res) => {
        if (loading) {
          wx.hideLoading()
        }

        const { statusCode, data: responseData } = res

        // HTTP状态码检查
        if (statusCode === STATUS_CODE.SUCCESS) {
          // 业务状态码检查
          if (responseData.code === STATUS_CODE.SUCCESS) {
            resolve(responseData)
          } else {
            handleBusinessError(responseData, showError)
            reject(responseData)
          }
        } else {
          handleHttpError(statusCode, showError)
          reject(res)
        }
      },
      fail: (error) => {
        if (loading) {
          wx.hideLoading()
        }

        handleNetworkError(error, showError)
        reject(error)
      }
    })
  })
}

/**
 * 处理业务错误
 */
function handleBusinessError(response, showError) {
  const { code, message } = response

  console.error('业务错误:', response)

  // 处理特殊错误码
  switch (code) {
    case STATUS_CODE.UNAUTHORIZED:
      // token过期或无效，跳转登录
      app.logout()
      return
    case STATUS_CODE.FORBIDDEN:
      // 权限不足
      if (showError) {
        wx.showToast({
          title: '权限不足',
          icon: 'error'
        })
      }
      break
    default:
      if (showError && message) {
        wx.showToast({
          title: message,
          icon: 'error'
        })
      }
  }
}

/**
 * 处理HTTP错误
 */
function handleHttpError(statusCode, showError) {
  console.error('HTTP错误:', statusCode)

  if (!showError) return

  let message = '网络错误'
  switch (statusCode) {
    case STATUS_CODE.NOT_FOUND:
      message = '请求的资源不存在'
      break
    case STATUS_CODE.SERVER_ERROR:
      message = '服务器内部错误'
      break
    default:
      message = `网络错误 ${statusCode}`
  }

  wx.showToast({
    title: message,
    icon: 'error'
  })
}

/**
 * 处理网络错误
 */
function handleNetworkError(error, showError) {
  console.error('网络错误:', error)

  if (!showError) return

  let message = '网络连接失败'
  if (error.errMsg) {
    if (error.errMsg.includes('timeout')) {
      message = '请求超时'
    } else if (error.errMsg.includes('fail')) {
      message = '网络连接失败'
    }
  }

  wx.showToast({
    title: message,
    icon: 'error'
  })
}

