/**
 * 检查资料完整度
 */
function checkProfileComplete(profile) {
  const required = ['nickname', 'avatar', 'gender', 'birthday', 'city', 'height']
  const optional = ['occupation', 'education', 'interests', 'introduction']

  let completeness = 0
  let missingFields = []

  // 必填字段
  required.forEach(field => {
    if (profile[field]) {
      completeness += 15 // 必填字段占90%
    } else {
      missingFields.push(field)
    }
  })

  // 选填字段
  optional.forEach(field => {
    if (profile[field] && profile[field].length > 0) {
      completeness += 2.5 // 选填字段占10%
    }
  })

  return {
    completeness: Math.min(completeness, 100),
    missingFields,
    isComplete: completeness >= 60 // 60%以上认为基本完整
  }
}

