// utils/utils.js - 通用工具函数

/**
 * 格式化时间
 * @param {Date|string|number} date 日期
 * @param {string} format 格式
 */
function formatTime(date, format = 'YYYY-MM-DD HH:mm:ss') {
  if (!date) return ''

  const d = new Date(date)
  if (isNaN(d.getTime())) return ''

  const year = d.getFullYear()
  const month = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  const hour = String(d.getHours()).padStart(2, '0')
  const minute = String(d.getMinutes()).padStart(2, '0')
  const second = String(d.getSeconds()).padStart(2, '0')

  return format
    .replace(/YYYY/g, year)
    .replace(/MM/g, month)
    .replace(/DD/g, day)
    .replace(/HH/g, hour)
    .replace(/mm/g, minute)
    .replace(/ss/g, second)
}

/**
 * 计算年龄
 * @param {Date|string} birthday 生日
 */
function calculateAge(birthday) {
  if (!birthday) return 0

  const birth = new Date(birthday)
  const now = new Date()

  let age = now.getFullYear() - birth.getFullYear()
  const monthDiff = now.getMonth() - birth.getMonth()

  if (monthDiff < 0 || (monthDiff === 0 && now.getDate() < birth.getDate())) {
    age--
  }

  return age
}

/**
 * 格式化距离
 * @param {number} distance 距离（米）
 */
function formatDistance(distance) {
  if (!distance || distance < 0) return ''

  if (distance < 1000) {
    return `${Math.round(distance)}m`
  } else if (distance < 10000) {
    return `${(distance / 1000).toFixed(1)}km`
  } else {
    return `${Math.round(distance / 1000)}km`
  }
}

/**
 * 格式化时间差（相对时间）
 * @param {Date|string|number} date 日期
 */
function formatRelativeTime(date) {
  if (!date) return ''

  const now = new Date()
  const target = new Date(date)
  const diff = now.getTime() - target.getTime()

  if (diff < 0) return '刚刚'

  const minute = 60 * 1000
  const hour = 60 * minute
  const day = 24 * hour
  const week = 7 * day
  const month = 30 * day
  const year = 365 * day

  if (diff < minute) {
    return '刚刚'
  } else if (diff < hour) {
    return `${Math.floor(diff / minute)}分钟前`
  } else if (diff < day) {
    return `${Math.floor(diff / hour)}小时前`
  } else if (diff < week) {
    return `${Math.floor(diff / day)}天前`
  } else if (diff < month) {
    return `${Math.floor(diff / week)}周前`
  } else if (diff < year) {
    return `${Math.floor(diff / month)}个月前`
  } else {
    return `${Math.floor(diff / year)}年前`
  }
}

/**
 * 格式化聊天时间
 * @param {Date|string|number} date 日期
 */
function formatChatTime(date) {
  if (!date) return ''

  const now = new Date()
  const target = new Date(date)
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const targetDay = new Date(target.getFullYear(), target.getMonth(), target.getDate())

  const diffDays = Math.floor((today - targetDay) / (24 * 60 * 60 * 1000))

  if (diffDays === 0) {
    // 今天
    return formatTime(date, 'HH:mm')
  } else if (diffDays === 1) {
    // 昨天
    return '昨天 ' + formatTime(date, 'HH:mm')
  } else if (diffDays < 7) {
    // 一周内
    const weekdays = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']
    return weekdays[target.getDay()] + ' ' + formatTime(date, 'HH:mm')
  } else if (now.getFullYear() === target.getFullYear()) {
    // 今年
    return formatTime(date, 'MM-DD HH:mm')
  } else {
    // 去年及以前
    return formatTime(date, 'YYYY-MM-DD')
  }
}

/**
 * 防抖函数
 * @param {Function} func 要防抖的函数
 * @param {number} wait 等待时间
 */
function debounce(func, wait = 300) {
  let timeout
  return function(...args) {
    const context = this
    clearTimeout(timeout)
    timeout = setTimeout(() => {
      func.apply(context, args)
    }, wait)
  }
}

/**
 * 节流函数
 * @param {Function} func 要节流的函数
 * @param {number} wait 等待时间
 */
function throttle(func, wait = 300) {
  let inThrottle
  return function(...args) {
    const context = this
    if (!inThrottle) {
      func.apply(context, args)
      inThrottle = true
      setTimeout(() => {
        inThrottle = false
      }, wait)
    }
  }
}

/**
 * 深拷贝
 * @param {any} obj 要拷贝的对象
 */
function deepClone(obj) {
  if (obj === null || typeof obj !== 'object') return obj
  if (obj instanceof Date) return new Date(obj)
  if (obj instanceof Array) return obj.map(item => deepClone(item))
  if (typeof obj === 'object') {
    const copy = {}
    Object.keys(obj).forEach(key => {
      copy[key] = deepClone(obj[key])
    })
    return copy
  }
}

/**
 * 生成UUID
 */
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0
    const v = c === 'x' ? r : (r & 0x3 | 0x8)
    return v.toString(16)
  })
}

/**
 * 数组去重
 * @param {Array} arr 数组
 * @param {string} key 去重的键名（对象数组）
 */
function uniqueArray(arr, key) {
  if (!key) {
    return [...new Set(arr)]
  }

  const seen = new Set()
  return arr.filter(item => {
    const value = item[key]
    if (seen.has(value)) {
      return false
    }
    seen.add(value)
    return true
  })
}

/**
 * 随机打乱数组
 * @param {Array} arr 数组
 */
function shuffleArray(arr) {
  const result = [...arr]
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[result[i], result[j]] = [result[j], result[i]]
  }
  return result
}

/**
 * 计算两点距离（经纬度）
 * @param {number} lat1 纬度1
 * @param {number} lng1 经度1
 * @param {number} lat2 纬度2
 * @param {number} lng2 经度2
 */
function calculateDistance(lat1, lng1, lat2, lng2) {
  const R = 6371000 // 地球半径（米）
  const dLat = (lat2 - lat1) * Math.PI / 180
  const dLng = (lng2 - lng1) * Math.PI / 180
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLng / 2) * Math.sin(dLng / 2)
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return R * c
}

/**
 * 手机号脱敏
 * @param {string} phone 手机号
 */
function maskPhone(phone) {
  if (!phone) return ''
  return phone.replace(/(\d{3})\d{4}(\d{4})/, '$1****$2')
}

/**
 * 身份证脱敏
 * @param {string} idCard 身份证号
 */
function maskIdCard(idCard) {
  if (!idCard) return ''
  return idCard.replace(/(\d{6})\d{8}(\d{4})/, '$1********$2')
}

/**
 * 姓名脱敏
 * @param {string} name 姓名
 */
function maskName(name) {
  if (!name) return ''
  if (name.length <= 2) {
    return name.charAt(0) + '*'
  }
  return name.charAt(0) + '*'.repeat(name.length - 2) + name.charAt(name.length - 1)
}

/**
 * 验证手机号
 * @param {string} phone 手机号
 */
function validatePhone(phone) {
  return /^1[3-9]\d{9}$/.test(phone)
}

/**
 * 验证身份证号
 * @param {string} idCard 身份证号
 */
function validateIdCard(idCard) {
  return /^[1-9]\d{5}(18|19|20)\d{2}((0[1-9])|(1[0-2]))(([0-2][1-9])|10|20|30|31)\d{3}[0-9Xx]$/.test(idCard)
}

/**
 * 验证邮箱
 * @param {string} email 邮箱
 */
function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

/**
 * 格式化数字（千分位）
 * @param {number} num 数字
 */
function formatNumber(num) {
  if (!num && num !== 0) return ''
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

/**
 * 获取文件扩展名
 * @param {string} filename 文件名
 */
function getFileExtension(filename) {
  if (!filename) return ''
  return filename.split('.').pop().toLowerCase()
}

/**
 * 检查图片格式
 * @param {string} filename 文件名
 */
function isImage(filename) {
  const imageExts = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp']
  return imageExts.includes(getFileExtension(filename))
}

/**
 * 检查视频格式
 * @param {string} filename 文件名
 */
function isVideo(filename) {
  const videoExts = ['mp4', 'mov', 'avi', 'wmv', 'flv', 'webm']
  return videoExts.includes(getFileExtension(filename))
}

/**
 * 压缩图片
 * @param {string} src 图片路径
 * @param {number} quality 压缩质量 0-1
 */
function compressImage(src, quality = 0.8) {
  return new Promise((resolve, reject) => {
    wx.compressImage({
      src,
      quality: quality * 100,
      success: resolve,
      fail: reject
    })
  })
}

/**
 * 保存图片到相册
 * @param {string} filePath 图片路径
 */
function saveImageToPhotosAlbum(filePath) {
  return new Promise((resolve, reject) => {
    wx.saveImageToPhotosAlbum({
      filePath,
      success: resolve,
      fail: reject
    })
  })
}

/**
 * 预览图片
 * @param {string|Array} urls 图片地址
 * @param {number} current 当前图片索引
 */
function previewImage(urls, current = 0) {
  const urlList = Array.isArray(urls) ? urls : [urls]
  wx.previewImage({
    urls: urlList,
    current: urlList[current]
  })
}

/**
 * 复制文本
 * @param {string} text 要复制的文本
 */
function copyText(text) {
  return new Promise((resolve, reject) => {
    wx.setClipboardData({
      data: text,
      success: resolve,
      fail: reject
    })
  })
}

/**
 * 震动反馈
 * @param {string} type 震动类型
 */
function vibrate(type = 'success') {
  if (wx.canIUse('vibrateShort')) {
    const typeMap = {
      success: 'light',
      warning: 'medium',
      error: 'heavy'
    }
    wx.vibrateShort({
      type: typeMap[type] || 'light'
    })
  }
}

/**
 * 音频反馈
 */
function playAudio(type = 'click') {
  // 可以预设一些音效文件
  const audioMap = {
    click: '/static/audio/click.mp3',
    success: '/static/audio/success.mp3',
    error: '/static/audio/error.mp3'
  }

  const audioSrc = audioMap[type]
  if (audioSrc) {
    const audioContext = wx.createInnerAudioContext()
    audioContext.src = audioSrc
    audioContext.play()
    audioContext.onEnded(() => {
      audioContext.destroy()
    })
  }
}

/**
 * 页面埋点
 * @param {string} event 事件名
 * @param {Object} params 参数
 */
function track(event, params = {}) {
  const app = getApp()
  if (app.globalData.isLogin) {
    const api = require('./api.js')
    api.trackEvent({
      event,
      params: {
        ...params,
        timestamp: Date.now(),
        page: getCurrentPages().pop().route
      }
    }).catch(error => {
      console.error('埋点上报失败:', error)
    })
  }
}

/**
 * 获取当前页面
 */
function getCurrentPage() {
  const pages = getCurrentPages()
  return pages[pages.length - 1]
}

/**
 * 页面跳转（带登录检查）
 * @param {string} url 页面地址
 * @param {boolean} needLogin 是否需要登录
 */
function navigateTo(url, needLogin = false) {
  if (needLogin) {
    const auth = require('./auth.js')
    if (!auth.checkLogin()) {
      wx.showModal({
        title: '需要登录',
        content: '请先登录后再使用此功能',
        showCancel: false,
        success: () => {
          wx.redirectTo({
            url: '/pages/login/login'
          })
        }
      })
      return
    }
  }

  wx.navigateTo({ url })
}

module.exports = {
  formatTime,
  calculateAge,
  formatDistance,
  formatRelativeTime,
  formatChatTime,
  debounce,
  throttle,
  deepClone,
  generateUUID,
  uniqueArray,
  shuffleArray,
  calculateDistance,
  maskPhone,
  maskIdCard,
  maskName,
  validatePhone,
  validateIdCard,
  validateEmail,
  formatNumber,
  getFileExtension,
  isImage,
  isVideo,
  compressImage,
  saveImageToPhotosAlbum,
  previewImage,
  copyText,
  vibrate,
  playAudio,
  track,
  getCurrentPage,
  navigateTo
}

// pages/home/home.js
const app = getApp()
const api = require('../../utils/api.js')
const utils = require('../../utils/utils.js')
const auth = require('../../utils/auth.js')

Page({
  data: {
    // 推荐用户列表
    recommendUsers: [],
    visibleCards: [], // 可见的卡片
    currentIndex: 0,
    loading: true,

    // 滑动相关
    startX: 0,
    startY: 0,
    deltaX: 0,
    deltaY: 0,
    showSwipeHint: false,
    swipeDirection: '',

    // 筛选相关
    showFilterModal: false,
    filterData: {
      minAge: 18,
      maxAge: 35,
      distance: 50,
      education: [],
      minHeight: 150,
      maxHeight: 185
    },

    // 筛选选项
    distanceOptions: [
      { label: '附近1公里', value: 1 },
      { label: '附近5公里', value: 5 },
      { label: '附近10公里', value: 10 },
      { label: '附近50公里', value: 50 },
      { label: '不限距离', value: 0 }
    ],

    educationOptions: [
      { label: '高中及以下', value: 'high_school' },
      { label: '大专', value: 'college' },
      { label: '本科', value: 'bachelor' },
      { label: '硕士', value: 'master' },
      { label: '博士', value: 'doctor' }
    ],

    // 统计数据
    todayLikes: 0,
    totalMatches: 0,
    todayVisitors: 0,

    // 匹配弹窗
    showMatchModal: false,
    matchedUser: null
  },

  onLoad(options) {
    console.log('首页加载', options)
    this.checkLoginAndInit()
  },

  onShow() {
    // 刷新统计数据
    this.refreshStats()

    // 如果用户刚注册，显示引导
    if (this.data.recommendUsers.length === 0) {
      this.loadRecommendUsers()
    }
  },

  onPullDownRefresh() {
    this.loadRecommendUsers()
    wx.stopPullDownRefresh()
  },

  onReachBottom() {
    this.loadMoreUsers()
  },

  // 检查登录状态并初始化
  async checkLoginAndInit() {
    if (!auth.checkLogin()) {
      wx.redirectTo({
        url: '/pages/login/login'
      })
      return
    }

    // 检查资料完整度
    const profile = app.getProfile()
    if (profile) {
      const { completeness } = auth.checkProfileComplete(profile)
      if (completeness < 60) {
        this.showProfileTip()
      }
    }

    await this.loadRecommendUsers()
    this.refreshStats()
  },

  // 显示完善资料提示
  showProfileTip() {
    wx.showModal({
      title: '完善资料',
      content: '完善个人资料可以获得3倍曝光机会，获得更多匹配',
      confirmText: '去完善',
      cancelText: '稍后',
      success: (res) => {
        if (res.confirm) {
          wx.navigateTo({
            url: '/pages/profile/profile?edit=true'
          })
        }
      }
    })
  },

  // 加载推荐用户
  async loadRecommendUsers() {
    try {
      this.setData({ loading: true })

      const location = app.globalData.currentLocation
      const params = {
        ...this.data.filterData,
        latitude: location?.latitude,
        longitude: location?.longitude,
        limit: 20
      }

      const res = await api.getRecommendUsers(params)
      if (res.code === 200) {
        const users = res.data.users.map((user, index) => ({
          ...user,
          index,
          age: utils.calculateAge(user.birthday),
          distanceText: user.distance ? utils.formatDistance(user.distance) : ''
        }))

        this.setData({
          recommendUsers: users,
          visibleCards: users.slice(0, 3), // 显示前3张卡片
          currentIndex: 0,
          loading: false
        })

        // 埋点
        utils.track('recommend_users_loaded', {
          count: users.length,
          filters: this.data.filterData
        })
      }
    } catch (error) {
      console.error('加载推荐用户失败:', error)
      this.setData({ loading: false })
      wx.showToast({
        title: '加载失败',
        icon: 'error'
      })
    }
  },

  // 加载更多用户
  async loadMoreUsers() {
    if (this.data.loading || this.data.currentIndex >= this.data.recommendUsers.length - 1) {
      return
    }

    try {
      const location = app.globalData.currentLocation
      const params = {
        ...this.data.filterData,
        latitude: location?.latitude,
        longitude: location?.longitude,
        offset: this.data.recommendUsers.length,
        limit: 10
      }

      const res = await api.getRecommendUsers(params)
      if (res.code === 200 && res.data.users.length > 0) {
        const newUsers = res.data.users.map((user, index) => ({
          ...user,
          index: this.data.recommendUsers.length + index,
          age: utils.calculateAge(user.birthday),
          distanceText: user.distance ? utils.formatDistance(user.distance) : ''
        }))

        this.setData({
          recommendUsers: [...this.data.recommendUsers, ...newUsers]
        })
      }
    } catch (error) {
      console.error('加载更多用户失败:', error)
    }
  },

  // 刷新统计数据
  async refreshStats() {
    try {
      const [likesRes, matchesRes, visitorsRes] = await Promise.all([
        api.getLikedUsers({ today: true }),
        api.getMatches(),
        api.getVisitors({ today: true })
      ])

      this.setData({
        todayLikes: likesRes.code === 200 ? likesRes.data.total : 0,
        totalMatches: matchesRes.code === 200 ? matchesRes.data.total : 0,
        todayVisitors: visitorsRes.code === 200 ? visitorsRes.data.total : 0
      })
    } catch (error) {
      console.error('刷新统计数据失败:', error)
    }
  },

  // 触摸开始
  onTouchStart(e) {
    const { clientX, clientY } = e.touches[0]
    this.setData({
      startX: clientX,
      startY: clientY,
      deltaX: 0,
      deltaY: 0
    })
  },

  // 触摸移动
  onTouchMove(e) {
    const { clientX, clientY } = e.touches[0]
    const deltaX = clientX - this.data.startX
    const deltaY = clientY - this.data.startY

    // 判断是否为水平滑动
    if (Math.abs(deltaX) > Math.abs(deltaY) && Math.abs(deltaX) > 20) {
      const direction = deltaX > 0 ? 'like' : 'dislike'
      this.setData({
        deltaX,
        deltaY,
        showSwipeHint: true,
        swipeDirection: direction
      })
    }
  },

  // 触摸结束
  onTouchEnd(e) {
    const { deltaX } = this.data

    this.setData({
      showSwipeHint: false,
      swipeDirection: ''
    })

    // 判断滑动距离是否足够
    if (Math.abs(deltaX) > 100) {
      const currentUser = this.data.visibleCards.find(card => card.index === this.data.currentIndex)
      if (currentUser) {
        if (deltaX > 0) {
          this.likeUser({ currentTarget: { dataset: { uid: currentUser.uid } } })
        } else {
          this.dislikeUser({ currentTarget: { dataset: { uid: currentUser.uid } } })
        }
      }
    }
  },

  // 喜欢用户
  async likeUser(e) {
    const { uid } = e.currentTarget.dataset

    try {
      const res = await api.likeUser(uid)
      if (res.code === 200) {
        // 触觉反馈
        utils.vibrate('success')

        // 检查是否匹配
        if (res.data.isMatch) {
          const matchedUser = this.data.recommendUsers.find(user => user.uid === uid)
          this.setData({
            showMatchModal: true,
            matchedUser
          })

          // 埋点
          utils.track('user_matched', {
            targetUid: uid,
            source: 'like'
          })
        }

        this.nextCard()

        // 埋点
        utils.track('user_liked', {
          targetUid: uid,
          source: 'button'
        })

        // 更新今日喜欢数
        this.setData({
          todayLikes: this.data.todayLikes + 1
        })
      }
    } catch (error) {
      console.error('喜欢用户失败:', error)
      wx.showToast({
        title: '操作失败',
        icon: 'error'
      })
    }
  },

  // 不喜欢用户
  async dislikeUser(e) {
    const { uid } = e.currentTarget.dataset

    // 触觉反馈
    utils.vibrate('light')

    this.nextCard()

    // 埋点
    utils.track('user_disliked', {
      targetUid: uid,
      source: 'button'
    })
  },

  // 超级喜欢
  async superLikeUser(e) {
    const { uid } = e.currentTarget.dataset

    // 检查是否为VIP用户
    const userInfo = app.getUserInfo()
    if (!userInfo.isVip) {
      wx.showModal({
        title: '超级喜欢',
        content: '开通会员可使用超级喜欢功能，让对方优先看到你',
        confirmText: '开通会员',
        success: (res) => {
          if (res.confirm) {
            wx.navigateTo({
              url: '/pages/vip/vip'
            })
          }
        }
      })
      return
    }

    try {
      const res = await api.superLikeUser(uid)
      if (res.code === 200) {
        // 触觉反馈
        utils.vibrate('success')

        wx.showToast({
          title: '超级喜欢发送成功',
          icon: 'success'
        })

        this.nextCard()

        // 埋点
        utils.track('user_super_liked', {
          targetUid: uid
        })
      }
    } catch (error) {
      console.error('超级喜欢失败:', error)
      wx.showToast({
        title: '操作失败',
        icon: 'error'
      })
    }
  },

  // 下一张卡片
  nextCard() {
    const newIndex = this.data.currentIndex + 1

    if (newIndex < this.data.recommendUsers.length) {
      // 更新可见卡片
      const visibleCards = this.data.recommendUsers.slice(newIndex, newIndex + 3)

      this.setData({
        currentIndex: newIndex,
        visibleCards
      })

      // 如果接近底部，加载更多
      if (newIndex >= this.data.recommendUsers.length - 5) {
        this.loadMoreUsers()
      }
    } else {
      // 没有更多用户了
      this.setData({
        visibleCards: [],
        currentIndex: this.data.recommendUsers.length
      })

      wx.showToast({
        title: '暂无更多用户',
        icon: 'none'
      })
    }
  },

  // 图片加载完成
  onImageLoad(e) {
    console.log('图片加载完成')
  },

  // 图片加载失败
  onImageError(e) {
    console.log('图片加载失败', e)
  },

  // 显示筛选弹窗
  showFilter() {
    this.setData({ showFilterModal: true })
  },

  // 隐藏筛选弹窗
  hideFilter() {
    this.setData({ showFilterModal: false })
  },

  // 年龄最小值变化
  onAgeMinChange(e) {
    const minAge = e.detail.value
    this.setData({
      'filterData.minAge': minAge,
      'filterData.maxAge': Math.max(minAge, this.data.filterData.maxAge)
    })
  },

  // 年龄最大值变化
  onAgeMaxChange(e) {
    const maxAge = e.detail.value
    this.setData({
      'filterData.maxAge': maxAge,
      'filterData.minAge': Math.min(maxAge, this.data.filterData.minAge)
    })
  },

  // 距离变化
  onDistanceChange(e) {
    this.setData({
      'filterData.distance': parseInt(e.detail.value)
    })
  },

  // 学历变化
  onEducationChange(e) {
    this.setData({
      'filterData.education': e.detail.value
    })
  },

  // 身高最小值变化
  onHeightMinChange(e) {
    const minHeight = e.detail.value
    this.setData({
      'filterData.minHeight': minHeight,
      'filterData.maxHeight': Math.max(minHeight, this.data.filterData.maxHeight)
    })
  },

  // 身高最大值变化
  onHeightMaxChange(e) {
    const maxHeight = e.detail.value
    this.setData({
      'filterData.maxHeight': maxHeight,
      'filterData.minHeight': Math.min(maxHeight, this.data.filterData.minHeight)
    })
  },

  // 重置筛选
  resetFilter() {
    this.setData({
      filterData: {
        minAge: 18,
        maxAge: 35,
        distance: 50,
        education: [],
        minHeight: 150,
        maxHeight: 185
      }
    })
  },

  // 应用筛选
  applyFilter() {
    this.hideFilter()
    this.loadRecommendUsers()

    // 埋点
    utils.track('filter_applied', {
      filters: this.data.filterData
    })
  },

  // 隐藏匹配弹窗
  hideMatchModal() {
    this.setData({
      showMatchModal: false,
      matchedUser: null
    })
  },

  // 去聊天
  goToChat(e) {
    const { matchId } = e.detail
    this.hideMatchModal()
    wx.navigateTo({
      url: `/pages/chatRoom/chatRoom?matchId=${matchId}`
    })
  },

  // 页面跳转
  goToSearch() {
    wx.switchTab({
      url: '/pages/search/search'
    })
  },

  goToProfile() {
    wx.switchTab({
      url: '/pages/profile/profile'
    })
  },

  goToLikes() {
    wx.navigateTo({
      url: '/pages/likes/likes'
    })
  },

  goToMatches() {
    wx.switchTab({
      url: '/pages/chat/chat'
    })
  },

  goToVisitors() {
    wx.navigateTo({
      url: '/pages/visitors/visitors'
    })
  }
})

/* pages/home/home.wxss */

.home-container {
  padding-top: 20rpx;
  padding-bottom: calc(env(safe-area-inset-bottom) + 120rpx);
  min-height: 100vh;
  background: linear-gradient(135deg, #FFE4E8 0%, #FFF5F7 100%);
}

/* 顶部搜索栏 */
.header {
  display: flex;
  align-items: center;
  padding: 0 32rpx 20rpx;
  gap: 16rpx;
}

.search-bar {
  flex: 1;
  display: flex;
  align-items: center;
  padding: 20rpx 24rpx;
  background-color: var(--white);
  border-radius: 50rpx;
  box-shadow: 0 2rpx 12rpx rgba(255, 107, 138, 0.1);
}

.search-icon {
  margin-right: 16rpx;
  opacity: 0.6;
}

.search-text {
  flex: 1;
  color: var(--text-lighter);
  font-size: 28rpx;
}

.filter-btn {
  width: 80rpx;
  height: 80rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--white);
  border-radius: 50%;
  box-shadow: 0 2rpx 12rpx rgba(255, 107, 138, 0.1);
}

/* 卡片容器 */
.cards-container {
  padding: 0 32rpx;
}

.card-stack {
  position: relative;
  height: 750rpx;
  display: flex;
  justify-content: center;
  align-items: center;
}

.user-card {
  position: absolute;
  width: 100%;
  max-width: 600rpx;
  background-color: var(--white);
  border-radius: 24rpx;
  box-shadow: 0 8rpx 32rpx rgba(0, 0, 0, 0.12);
  overflow: hidden;
  transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.user-card.active {
  z-index: 3 !important;
}

/* 用户头像区域 */
.card-image {
  position: relative;
  height: 400rpx;
  overflow: hidden;
}

.avatar {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.online-status {
  position: absolute;
