// components/userCard/userCard.js
const utils = require('../../utils/utils.js')

Component({
  properties: {
    // 用户数据
    user: {
      type: Object,
      value: {},
      observer(newVal) {
        this.processUserData(newVal)
      }
    },

    // 显示配置
    showOnlineStatus: {
      type: Boolean,
      value: true
    },

    showVerifyBadges: {
      type: Boolean,
      value: true
    },

    showDetailInfo: {
      type: Boolean,
      value: true
    },

    showInterests: {
      type: Boolean,
      value: true
    },

    showIntroduction: {
      type: Boolean,
      value: true
    },

    showLastActive: {
      type: Boolean,
      value: false
    },

    showActions: {
      type: Boolean,
      value: false
    },

    showSuperLike: {
      type: Boolean,
      value: true
    },

    // 兴趣标签最大显示数量
    maxInterests: {
      type: Number,
      value: 3
    },

    // 自定义样式类名
    className: {
      type: String,
      value: ''
    },

    // 遮罩层
    showOverlay: {
      type: Boolean,
      value: false
    },

    overlayType: {
      type: String,
      value: 'like' // like, dislike, match
    },

    overlayText: {
      type: String,
      value: ''
    },

    overlayIcon: {
      type: String,
      value: 'success'
    }
  },

  data: {
    imageLoaded: false,
    imageError: false
  },

  methods: {
    // 处理用户数据
    processUserData(user) {
      if (!user || !user.uid) return

      // 计算年龄
      if (user.birthday && !user.age) {
        user.age = utils.calculateAge(user.birthday)
      }

      // 格式化距离
      if (user.distance && !user.distanceText) {
        user.distanceText = utils.formatDistance(user.distance)
      }

      // 格式化最后活跃时间
      if (user.lastActiveTime && !user.lastActiveText) {
        user.lastActiveText = this.formatLastActiveTime(user.lastActiveTime)
      }

      // 检查是否为新用户（注册时间小于7天）
      if (user.registeredAt && !user.hasOwnProperty('isNewUser')) {
        const daysSinceRegistered = (Date.now() - new Date(user.registeredAt).getTime()) / (1000 * 60 * 60 * 24)
        user.isNewUser = daysSinceRegistered <= 7
      }

      this.setData({ user })
    },

    // 格式化最后活跃时间
    formatLastActiveTime(lastActiveTime) {
      const now = new Date()
      const activeTime = new Date(lastActiveTime)
      const diffMinutes = Math.floor((now - activeTime) / (1000 * 60))

      if (diffMinutes < 5) {
        return '刚刚活跃'
      } else if (diffMinutes < 60) {
        return `${diffMinutes}分钟前活跃`
      } else if (diffMinutes < 1440) { // 24小时
        const diffHours = Math.floor(diffMinutes / 60)
        return `${diffHours}小时前活跃`
      } else {
        const diffDays = Math.floor(diffMinutes / 1440)
        if (diffDays === 1) {
          return '昨天活跃'
        } else if (diffDays < 7) {
          return `${diffDays}天前活跃`
        } else {
          return '很久未活跃'
        }
      }
    },

    // 图片加载完成
    onImageLoad() {
      this.setData({ 
        imageLoaded: true,
        imageError: false 
      })
    },

    // 图片加载失败
    onImageError() {
      this.setData({ 
        imageLoaded: false,
        imageError: true 
      })

      // 使用默认头像
      const user = this.data.user
      user.avatar = '/static/images/default-avatar.png'
      this.setData({ user })
    },

    // 卡片点击
    onCardTap() {
      const { user } = this.data

      // 记录访问
      this.recordVisit(user.uid)

      // 触发点击事件
      this.triggerEvent('tap', {
        user,
        uid: user.uid
      })
    },

    // 喜欢按钮
    onLike() {
      const { user } = this.data

      // 触觉反馈
      utils.vibrate('success')

      this.triggerEvent('like', {
        user,
        uid: user.uid
      })

      // 埋点
      utils.track('user_card_like', {
        targetUid: user.uid,
        source: 'card'
      })
    },

    // 不喜欢按钮
    onDislike() {
      const { user } = this.data

      // 触觉反馈
      utils.vibrate('light')

      this.triggerEvent('dislike', {
        user,
        uid: user.uid
      })

      // 埋点
      utils.track('user_card_dislike', {
        targetUid: user.uid,
        source: 'card'
      })
    },

    // 超级喜欢按钮
    onSuperLike() {
      const { user } = this.data

      // 触觉反馈
      utils.vibrate('success')

      this.triggerEvent('superlike', {
        user,
        uid: user.uid
      })

      // 埋点
      utils.track('user_card_super_like', {
        targetUid: user.uid,
        source: 'card'
      })
    },

    // 记录访问
    recordVisit(uid) {
      if (!uid) return

      // 防抖处理，避免重复记录
      if (this.visitTimer) {
        clearTimeout(this.visitTimer)
      }

      this.visitTimer = setTimeout(() => {
        const api = require('../../utils/api.js')
        api.recordVisit(uid).catch(error => {
          console.error('记录访问失败:', error)
        })
      }, 1000)
    },

    // 显示遮罩
    showOverlay(type, text, icon) {
      this.setData({
        showOverlay: true,
        overlayType: type,
        overlayText: text,
        overlayIcon: icon
      })

      // 自动隐藏
      setTimeout(() => {
        this.hideOverlay()
      }, 1500)
    },

    // 隐藏遮罩
    hideOverlay() {
      this.setData({
        showOverlay: false
      })
    },

    // 设置卡片状态
    setCardState(state) {
      const states = {
        liked: {
          showOverlay: true,
          overlayType: 'like',
          overlayText: '喜欢',
          overlayIcon: 'success'
        },
        disliked: {
          showOverlay: true,
          overlayType: 'dislike',
          overlayText: '不喜欢',
          overlayIcon: 'clear'
        },
        matched: {
          showOverlay: true,
          overlayType: 'match',
          overlayText: '匹配成功',
          overlayIcon: 'success'
        }
      }

      if (states[state]) {
        this.setData(states[state])

        setTimeout(() => {
          this.hideOverlay()
        }, 2000)
      }
    }
  },

  attached() {
    // 组件初始化
    this.processUserData(this.data.user)
  },

  detached() {
    // 清理定时器
    if (this.visitTimer) {
      clearTimeout(this.visitTimer)
    }
  }
})

