// components/matchModal/matchModal.js
const app = getApp()
const utils = require('../../utils/utils.js')

Component({
  properties: {
    show: {
      type: Boolean,
      value: false,
      observer(newVal) {
        if (newVal) {
          this.onShow()
        } else {
          this.onHide()
        }
      }
    },

    user: {
      type: Object,
      value: {},
      observer(newVal) {
        this.processUserData(newVal)
      }
    }
  },

  data: {
    myAvatar: '',
    commonInterests: [],
    animationStarted: false
  },

  methods: {
    // 弹窗显示
    onShow() {
      // 获取当前用户头像
      const userInfo = app.getUserInfo()
      const profile = app.getProfile()

      this.setData({
        myAvatar: profile?.avatar || userInfo?.avatarUrl || '/static/images/default-avatar.png'
      })

      // 播放匹配成功音效
      this.playMatchSound()

      // 启动动画
      this.startAnimation()

      // 触觉反馈
      utils.vibrate('success')

      // 埋点
      utils.track('match_modal_show', {
        targetUid: this.data.user.uid
      })
    },

    // 弹窗隐藏
    onHide() {
      this.setData({
        animationStarted: false
      })

      // 停止画布动画
      this.stopCanvasAnimation()
    },

    // 处理用户数据
    processUserData(user) {
      if (!user || !user.uid) return

      // 计算年龄
      if (user.birthday && !user.age) {
        user.age = utils.calculateAge(user.birthday)
      }

      // 计算共同兴趣
      this.calculateCommonInterests(user)
    },

    // 计算共同兴趣
    calculateCommonInterests(user) {
      const profile = app.getProfile()
      const myInterests = profile?.interests || []
      const userInterests = user.interests || []

      const common = myInterests.filter(interest => 
        userInterests.includes(interest)
      )

      this.setData({
        commonInterests: common.slice(0, 3) // 最多显示3个
      })
    },

    // 播放匹配成功音效
    playMatchSound() {
      const audioContext = wx.createInnerAudioContext()
      audioContext.src = '/static/audio/match-success.mp3'
      audioContext.volume = 0.5
      audioContext.play()

      audioContext.onEnded(() => {
        audioContext.destroy()
      })

      audioContext.onError((error) => {
        console.error('音效播放失败:', error)
        audioContext.destroy()
      })
    },

    // 启动动画
    startAnimation() {
      this.setData({
        animationStarted: true
      })

      // 启动画布动画
      this.startCanvasAnimation()

      // CSS动画会自动触发
      setTimeout(() => {
        this.createHeartAnimation()
      }, 500)
    },

    // 创建爱心动画
    createHeartAnimation() {
      const hearts = ['heart-1', 'heart-2', 'heart-3']

      hearts.forEach((heart, index) => {
        setTimeout(() => {
          const query = this.createSelectorQuery()
          query.select(`.${heart}`).boundingClientRect()
          query.exec((res) => {
            if (res[0]) {
              this.animateHeart(`.${heart}`)
            }
          })
        }, index * 200)
      })
    },

    // 单个爱心动画
    animateHeart(selector) {
      const animation = wx.createAnimation({
        duration: 1000,
        timingFunction: 'ease-out'
      })

      animation.scale(1.2).opacity(1).step()
      animation.scale(1).opacity(0.8).step()

      this.setData({
        [`${selector.replace('.', '')}Animation`]: animation.export()
      })
    },

    // 启动画布动画（粒子效果）
    startCanvasAnimation() {
      const ctx = wx.createCanvasContext('matchCanvas', this)
      const systemInfo = app.globalData.systemInfo

      if (!systemInfo) return

      const canvasWidth = systemInfo.windowWidth
      const canvasHeight = systemInfo.windowHeight

      // 粒子数组
      const particles = []

      // 创建粒子
      for (let i = 0; i < 50; i++) {
        particles.push({
          x: Math.random() * canvasWidth,
          y: canvasHeight + Math.random() * 100,
          size: Math.random() * 6 + 2,
          speedY: Math.random() * 3 + 1,
          speedX: (Math.random() - 0.5) * 2,
          opacity: Math.random() * 0.8 + 0.2,
          color: this.getRandomColor()
        })
      }

      // 动画循环
      const animate = () => {
        if (!this.data.show) return

        ctx.clearRect(0, 0, canvasWidth, canvasHeight)

        particles.forEach((particle, index) => {
          // 更新位置
          particle.y -= particle.speedY
          particle.x += particle.speedX
          particle.opacity -= 0.005

          // 重置超出边界的粒子
          if (particle.y < -20 || particle.opacity <= 0) {
            particle.y = canvasHeight + Math.random() * 100
            particle.x = Math.random() * canvasWidth
            particle.opacity = Math.random() * 0.8 + 0.2
          }

          // 绘制粒子
          ctx.save()
          ctx.globalAlpha = particle.opacity
          ctx.fillStyle = particle.color
          ctx.beginPath()
          ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2)
          ctx.fill()
          ctx.restore()
        })

        ctx.draw()

        if (this.data.show) {
          requestAnimationFrame(animate)
        }
      }

      animate()
    },

    // 停止画布动画
    stopCanvasAnimation() {
      // 清空画布
      const ctx = wx.createCanvasContext('matchCanvas', this)
      const systemInfo = app.globalData.systemInfo

      if (systemInfo) {
        ctx.clearRect(0, 0, systemInfo.windowWidth, systemInfo.windowHeight)
        ctx.draw()
      }
    },

    // 获取随机颜色
    getRandomColor() {
      const colors = [
        '#FF6B8A', '#FFB6C1', '#FFC0CB', '#FFE4E1',
        '#FF69B4', '#FF1493', '#DC143C', '#B22222'
      ]
      return colors[Math.floor(Math.random() * colors.length)]
    },

    // 关闭弹窗
    onClose() {
      this.triggerEvent('close')

      // 埋点
      utils.track('match_modal_close', {
        targetUid: this.data.user.uid,
        action: 'close_button'
      })
    },

    // 点击遮罩关闭
    onMaskTap() {
      this.triggerEvent('close')

      // 埋点
      utils.track('match_modal_close', {
        targetUid: this.data.user.uid,
        action: 'mask_tap'
      })
    },

    // 继续寻找
    onKeepLooking() {
      this.triggerEvent('close')

      // 埋点
      utils.track('match_modal_action', {
        targetUid: this.data.user.uid,
        action: 'keep_looking'
      })
    },

    // 开始聊天
    onStartChat() {
      const { user } = this.data

      // 触发聊天事件
      this.triggerEvent('chat', {
        user,
        uid: user.uid,
        matchId: user.matchId
      })

      // 埋点
      utils.track('match_modal_action', {
        targetUid: user.uid,
        action: 'start_chat'
      })
    }
  },

  attached() {
    // 组件初始化
    console.log('匹配弹窗组件初始化')
  },

  detached() {
    // 组件销毁时清理
    this.stopCanvasAnimation()
  }
})

/* components/matchModal/matchModal.wxss */

.match-modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(255, 107, 138, 0.95), rgba(255, 182, 193, 0.95));
  backdrop-filter: blur(10rpx);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
}

.match-modal.show {
  opacity: 1;
  visibility: visible;
}

.modal-content {
  position: relative;
  background-color: var(--white);
  border-radius: 32rpx;
  padding: 48rpx 32rpx 32rpx;
  margin: 0 32rpx;
  max-width: 500rpx;
  width: 100%;
  text-align: center;
  box-shadow: 0 20rpx 60rpx rgba(0, 0, 0, 0.3);
  transform: scale(0.8) translateY(100rpx);
  transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.match-modal.show .modal-content {
  transform: scale(1) translateY(0);
}

/* 关闭按钮 */
.close-btn {
  position: absolute;
  top: 20rpx;
  right: 20rpx;
  width: 60rpx;
  height: 60rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background-color: rgba(0, 0, 0, 0.05);
  transition: background-color 0.2s ease;
}

.close-btn:active {
  background-color: rgba(0, 0, 0, 0.1);
}

/* 匹配成功动画区域 */
.match-animation {
  margin-bottom: 40rpx;
  position: relative;
}

.heart-container {
  position: relative;
  height: 120rpx;
  margin-bottom: 24rpx;
  display: flex;
  align-items: center;
  justify-content: center;
}

.heart {
  position: absolute;
  width: 40rpx;
  height: 40rpx;
  background-color: var(--primary-color);
  border-radius: 50%;
  opacity: 0;
  animation: heartPulse 2s infinite ease-in-out;
}

.heart::before,
.heart::after {
  content: '';
  position: absolute;
  width: 40rpx;
  height: 40rpx;
  background-color: var(--primary-color);
  border-radius: 50%;
}

.heart::before {
  top: -20rpx;
  left: 0;
}

.heart::after {
  left: 20rpx;
  top: 0;
}

.heart-1 {
  animation-delay: 0s;
  transform: scale(1);
}

.heart-2 {
  animation-delay: 0.3s;
  transform: scale(0.8);
}

.heart-3 {
  animation-delay: 0.6s;
  transform: scale(1.2);
}

.match-title {
  display: block;
  font-size: 48rpx;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 12rpx;
  animation: titleSlideUp 0.6s ease-out 0.5s both;
}

.match-subtitle {
  display: block;
  font-size: 28rpx;
  color: var(--text-light);
  animation: subtitleSlideUp 0.6s ease-out 0.7s both;
}

/* 头像容器 */
.avatars-container {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 32rpx;
  margin-bottom: 32rpx;
  animation: avatarsSlideUp 0.8s ease-out 0.9s both;
}

.avatar-item {
  position: relative;
  animation: avatarBounce 1s ease-out;
}

.avatar {
  width: 120rpx;
  height: 120rpx;
  border-radius: 50%;
  object-fit: cover;
}

.avatar-border {
  position: absolute;
  top: -6rpx;
  left: -6rpx;
  right: -6rpx;
  bottom: -6rpx;
  border: 6rpx solid var(--primary-color);
  border-radius: 50%;
  opacity: 0.3;
  animation: borderPulse 2s infinite ease-in-out;
}

.match-icon {
  width: 60rpx;
  height: 60rpx;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8rpx 24rpx rgba(255, 107, 138, 0.4);
  animation: iconSpin 1s ease-out;
}

/* 用户信息 */
.user-info {
  margin-bottom: 32rpx;
  animation: infoSlideUp 0.6s ease-out 1.1s both;
}

.user-name {
  display: block;
  font-size: 36rpx;
  font-weight: 600;
  color: var(--text-color);
  margin-bottom: 8rpx;
}

.user-age {
  font-size: 24rpx;
  color: var(--text-light);
  margin-right: 16rpx;
}

.user-city {
