  color: var(--text-lighter);
}

/* 共同兴趣 */
.common-interests {
  margin-bottom: 40rpx;
  animation: interestsSlideUp 0.6s ease-out 1.3s both;
}

.interests-title {
  display: block;
  font-size: 24rpx;
  color: var(--text-light);
  margin-bottom: 16rpx;
}

.interests-list {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12rpx;
}

.interest-tag {
  padding: 8rpx 16rpx;
  background: linear-gradient(135deg, rgba(255, 107, 138, 0.1), rgba(255, 182, 193, 0.1));
  color: var(--primary-color);
  font-size: 22rpx;
  border-radius: 20rpx;
  font-weight: 500;
  border: 1rpx solid rgba(255, 107, 138, 0.2);
}

/* 操作按钮 */
.modal-actions {
  display: flex;
  gap: 16rpx;
  margin-bottom: 24rpx;
  animation: actionsSlideUp 0.6s ease-out 1.5s both;
}

.modal-actions .btn {
  flex: 1;
  height: 88rpx;
  border-radius: 44rpx;
  font-size: 28rpx;
  font-weight: 500;
  transition: all 0.3s ease;
}

.modal-actions .btn-secondary {
  background-color: var(--bg-color);
  color: var(--text-color);
  border: 2rpx solid var(--border-color);
}

.modal-actions .btn-primary {
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  box-shadow: 0 8rpx 24rpx rgba(255, 107, 138, 0.3);
}

.modal-actions .btn:active {
  transform: scale(0.98);
}

/* 提示文案 */
.tips {
  animation: tipsSlideUp 0.6s ease-out 1.7s both;
}

.tip-text {
  font-size: 22rpx;
  color: var(--text-lighter);
  line-height: 1.4;
}

/* 背景画布 */
.match-canvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: -1;
}

/* 动画定义 */
@keyframes heartPulse {
  0%, 100% {
    opacity: 0;
    transform: scale(0.5);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes titleSlideUp {
  from {
    opacity: 0;
    transform: translateY(40rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes subtitleSlideUp {
  from {
    opacity: 0;
    transform: translateY(30rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes avatarsSlideUp {
  from {
    opacity: 0;
    transform: translateY(50rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes avatarBounce {
  0% {
    transform: scale(0);
  }
  50% {
    transform: scale(1.1);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes borderPulse {
  0%, 100% {
    opacity: 0.3;
    transform: scale(1);
  }
  50% {
    opacity: 0.6;
    transform: scale(1.05);
  }
}

@keyframes iconSpin {
  0% {
    transform: rotate(0deg) scale(0);
  }
  50% {
    transform: rotate(180deg) scale(1.2);
  }
  100% {
    transform: rotate(360deg) scale(1);
  }
}

@keyframes infoSlideUp {
  from {
    opacity: 0;
    transform: translateY(30rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes interestsSlideUp {
  from {
    opacity: 0;
    transform: translateY(30rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes actionsSlideUp {
  from {
    opacity: 0;
    transform: translateY(40rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes tipsSlideUp {
  from {
    opacity: 0;
    transform: translateY(20rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 响应式适配 */
@media (max-width: 320px) {
  .modal-content {
    margin: 0 24rpx;
    padding: 40rpx 24rpx 24rpx;
  }

  .match-title {
    font-size: 40rpx;
  }

  .avatar {
    width: 100rpx;
    height: 100rpx;
  }

  .avatars-container {
    gap: 24rpx;
  }

  .modal-actions .btn {
    height: 80rpx;
    font-size: 26rpx;
  }
}

/* 减少动画效果（针对低性能设备） */
@media (prefers-reduced-motion: reduce) {
  .match-modal,
  .modal-content,
  .heart,
  .match-title,
  .match-subtitle,
  .avatars-container,
  .avatar-item,
  .avatar-border,
  .match-icon,
  .user-info,
  .common-interests,
  .modal-actions,
  .tips {
    animation: none !important;
    transition: none !important;
  }

  .match-modal.show .modal-content {
    transform: none !important;
  }
}

