// pages/login/login.js
const app = getApp()
const api = require('../../utils/api.js')
const auth = require('../../utils/auth.js')
const utils = require('../../utils/utils.js')

Page({
  data: {
    // 登录方式: 'phone' | 'wechat'
    loginType: 'wechat',

    // 手机号登录相关
    phone: '',
    code: '',
    isValidPhone: false,
    showCodeInput: false,
    codeCountdown: 0,

    // 登录状态
    loginLoading: false,
    canLogin: false,

    // 服务条款
    agreedTerms: false,
    showAgreementModal: false,
    agreementTitle: '',
    agreementContent: '',

    // 引导页面
    showGuide: false
  },

  onLoad(options) {
    console.log('登录页面加载', options)

    // 检查是否首次访问
    const isFirstVisit = !wx.getStorageSync('hasVisited')
    if (isFirstVisit) {
      this.setData({ showGuide: true })
      wx.setStorageSync('hasVisited', true)
    }

    // 检查是否已登录
    if (auth.checkLogin()) {
      this.redirectToHome()
    }

    // 获取推荐的登录方式
    this.getRecommendedLoginType()

    // 埋点
    utils.track('login_page_view', {
      source: options.source || 'direct'
    })
  },

  onShow() {
    // 重置状态
    this.setData({
      loginLoading: false
    })
  },

  // 获取推荐的登录方式
  getRecommendedLoginType() {
    // 检查是否支持微信手机号授权
    if (wx.canIUse('button.open-type.getPhoneNumber')) {
      this.setData({ loginType: 'wechat' })
    } else {
      this.setData({ loginType: 'phone' })
    }
  },

  // 手机号输入
  onPhoneInput(e) {
    const phone = e.detail.value
    const isValid = utils.validatePhone(phone)

    this.setData({
      phone,
      isValidPhone: isValid,
      canLogin: isValid && this.data.agreedTerms
    })
  },

  // 验证码输入
  onCodeInput(e) {
    const code = e.detail.value
    this.setData({
      code,
      canLogin: code.length === 6 && this.data.agreedTerms
    })
  },

  // 发送验证码
  async sendCode() {
    if (!this.data.isValidPhone) {
      wx.showToast({
        title: '请输入正确的手机号',
        icon: 'error'
      })
      return
    }

    if (!this.data.agreedTerms) {
      wx.showToast({
        title: '请先同意用户协议',
        icon: 'error'
      })
      return
    }

    try {
      this.setData({ loginLoading: true })

      // 调用发送验证码接口
      const res = await api.sendSmsCode({
        phone: this.data.phone,
        type: 'login'
      })

      if (res.code === 200) {
        wx.showToast({
          title: '验证码已发送',
          icon: 'success'
        })

        this.setData({
          showCodeInput: true,
          codeCountdown: 60
        })

        this.startCountdown()

        // 埋点
        utils.track('sms_code_sent', {
          phone: utils.maskPhone(this.data.phone)
        })
      } else {
        throw new Error(res.message || '发送失败')
      }
    } catch (error) {
      console.error('发送验证码失败:', error)
      wx.showToast({
        title: error.message || '发送失败',
        icon: 'error'
      })
    } finally {
      this.setData({ loginLoading: false })
    }
  },

  // 开始倒计时
  startCountdown() {
    const timer = setInterval(() => {
      const countdown = this.data.codeCountdown - 1

      if (countdown <= 0) {
        clearInterval(timer)
        this.setData({ codeCountdown: 0 })
      } else {
        this.setData({ codeCountdown: countdown })
      }
    }, 1000)
  },

  // 手机号登录
  async phoneLogin() {
    if (!this.data.canLogin) return

    if (!this.data.showCodeInput) {
      // 第一步：发送验证码
      await this.sendCode()
      return
    }

    // 第二步：验证码登录
    if (!this.data.code || this.data.code.length !== 6) {
      wx.showToast({
        title: '请输入6位验证码',
        icon: 'error'
      })
      return
    }

    try {
      this.setData({ loginLoading: true })

      const res = await api.login({
        phone: this.data.phone,
        code: this.data.code,
        type: 'sms'
      })

      if (res.code === 200) {
        await this.handleLoginSuccess(res.data)

        // 埋点
        utils.track('login_success', {
          method: 'phone',
          phone: utils.maskPhone(this.data.phone),
          isFirstLogin: res.data.isFirstLogin
        })
      } else {
        throw new Error(res.message || '登录失败')
      }
    } catch (error) {
      console.error('手机号登录失败:', error)
      wx.showToast({
        title: error.message || '登录失败',
        icon: 'error'
      })
    } finally {
      this.setData({ loginLoading: false })
    }
  },

  // 微信手机号登录
  async wxPhoneLogin(e) {
    console.log('微信手机号登录', e.detail)

    if (e.detail.errMsg !== 'getPhoneNumber:ok') {
      console.log('用户拒绝授权手机号')
      return
    }

    if (!this.data.agreedTerms) {
      wx.showToast({
        title: '请先同意用户协议',
        icon: 'error'
      })
      return
    }

    try {
      this.setData({ loginLoading: true })

      const loginResult = await auth.phoneLogin(e.detail)

      if (loginResult.success) {
        await this.handleLoginSuccess({
          token: app.globalData.token,
          userInfo: loginResult.userInfo,
          isFirstLogin: loginResult.isFirstLogin
        })

        // 埋点
        utils.track('login_success', {
          method: 'wechat_phone',
          isFirstLogin: loginResult.isFirstLogin
        })
      } else {
        throw new Error(loginResult.error)
      }
    } catch (error) {
      console.error('微信手机号登录失败:', error)
      wx.showToast({
        title: error.message || '登录失败',
        icon: 'error'
      })
    } finally {
      this.setData({ loginLoading: false })
    }
  },

  // 微信授权登录
  async wxLogin() {
    if (!this.data.agreedTerms) {
      wx.showToast({
        title: '请先同意用户协议',
        icon: 'error'
      })
      return
    }

    try {
      this.setData({ loginLoading: true })

      const loginResult = await auth.login()

      if (loginResult.success) {
        await this.handleLoginSuccess({
          token: app.globalData.token,
          userInfo: loginResult.userInfo,
          isFirstLogin: loginResult.isFirstLogin
        })

        // 埋点
        utils.track('login_success', {
          method: 'wechat',
          isFirstLogin: loginResult.isFirstLogin
        })
      } else {
        throw new Error(loginResult.error)
      }
    } catch (error) {
      console.error('微信登录失败:', error)
      wx.showToast({
        title: error.message || '登录失败',
        icon: 'error'
      })
    } finally {
      this.setData({ loginLoading: false })
    }
  },

  // 处理登录成功
  async handleLoginSuccess(data) {
    const { token, userInfo, isFirstLogin } = data

    // 保存登录信息
    wx.setStorageSync('token', token)
    wx.setStorageSync('userInfo', userInfo)

    // 更新全局状态
    app.globalData.token = token
    app.globalData.userInfo = userInfo
    app.globalData.isLogin = true

    // 获取用户资料
    try {
      const profileRes = await api.getProfile(userInfo.uid)
      if (profileRes.code === 200) {
        app.updateProfile(profileRes.data)
      }
    } catch (error) {
      console.error('获取用户资料失败:', error)
    }

    // 显示登录成功提示
    wx.showToast({
      title: isFirstLogin ? '注册成功' : '登录成功',
      icon: 'success'
    })

    // 延迟跳转，让用户看到成功提示
    setTimeout(() => {
      if (isFirstLogin) {
        // 首次登录，跳转到资料完善页面
        wx.redirectTo({
          url: '/pages/register/register'
        })
      } else {
        // 已有用户，跳转到首页
        this.redirectToHome()
      }
    }, 1500)
  },

  // 跳转到首页
  redirectToHome() {
    wx.switchTab({
      url: '/pages/home/home'
    })
  },

  // 切换登录方式
  switchLoginType() {
    const newType = this.data.loginType === 'phone' ? 'wechat' : 'phone'
    this.setData({
      loginType: newType,
      phone: '',
      code: '',
      showCodeInput: false,
      codeCountdown: 0,
      isValidPhone: false,
      canLogin: false
    })

    // 埋点
    utils.track('login_type_switched', {
      from: this.data.loginType,
      to: newType
    })
  },

  // 切换协议同意状态
  toggleAgreement() {
    const agreed = !this.data.agreedTerms
    this.setData({
      agreedTerms: agreed,
      canLogin: agreed && (
        (this.data.loginType === 'phone' && this.data.isValidPhone) ||
        (this.data.loginType === 'phone' && this.data.showCodeInput && this.data.code.length === 6) ||
        this.data.loginType === 'wechat'
      )
    })
  },

  // 显示用户协议
  showUserAgreement() {
    this.setData({
      showAgreementModal: true,
      agreementTitle: '用户协议',
      agreementContent: this.getUserAgreementContent()
    })
  },

  // 显示隐私政策
  showPrivacyPolicy() {
    this.setData({
      showAgreementModal: true,
      agreementTitle: '隐私政策',
      agreementContent: this.getPrivacyPolicyContent()
    })
  },

  // 隐藏协议弹窗
  hideAgreementModal() {
    this.setData({
      showAgreementModal: false
    })
  },

  // 获取用户协议内容
  getUserAgreementContent() {
    return `
邂逅用户协议

欢迎您使用邂逅服务！

1. 服务说明
邂逅是一款专注于真实社交的婚恋交友平台。

2. 用户注册
用户需要提供真实、准确的个人信息进行注册。

3. 用户行为规范
用户应当遵守法律法规，不得发布违法违规内容。

4. 隐私保护
我们将严格保护用户的个人隐私和数据安全。

5. 服务变更
我们保留随时修改或终止服务的权利。

更多详细条款请访问我们的官方网站查看。
    `.trim()
  },

  // 获取隐私政策内容
  getPrivacyPolicyContent() {
    return `
邂逅隐私政策

我们深知个人信息对您的重要性，并会尽全力保护您的个人信息安全可靠。

1. 我们收集的信息
