- 撤回授权同意
- 注销账户

更多详细条款请访问我们的官方网站查看。
    `.trim()
  },

  // 隐藏引导页
  hideGuide() {
    this.setData({ showGuide: false })

    // 埋点
    utils.track('login_guide_closed')
  },

  // 第三方登录（预留）
  appleLogin() {
    wx.showToast({
      title: '功能开发中',
      icon: 'none'
    })
  },

  qqLogin() {
    wx.showToast({
      title: '功能开发中',
      icon: 'none'
    })
  },

  weiboLogin() {
    wx.showToast({
      title: '功能开发中',
