/* pages/login/login.wxss */

.login-container {
  min-height: 100vh;
  background: linear-gradient(135deg, #FFE4E8 0%, #FFF5F7 50%, #F0F8FF 100%);
  position: relative;
  overflow: hidden;
}

/* 背景装饰 */
.bg-decoration {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  z-index: 0;
}

.decoration-circle {
  position: absolute;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(255, 107, 138, 0.1), rgba(255, 182, 193, 0.05));
  animation: float 6s ease-in-out infinite;
}

.circle-1 {
  width: 200rpx;
  height: 200rpx;
  top: 10%;
  right: -50rpx;
  animation-delay: 0s;
}

.circle-2 {
  width: 150rpx;
  height: 150rpx;
  top: 60%;
  left: -30rpx;
  animation-delay: 2s;
}

.circle-3 {
  width: 120rpx;
  height: 120rpx;
  bottom: 20%;
  right: 20%;
  animation-delay: 4s;
}

/* 顶部Logo区域 */
.header-section {
  position: relative;
  z-index: 1;
  text-align: center;
  padding: 120rpx 32rpx 80rpx;
  animation: slideDown 0.8s ease-out;
}

.app-logo {
  width: 160rpx;
  height: 160rpx;
  margin-bottom: 32rpx;
  border-radius: 32rpx;
  box-shadow: 0 8rpx 32rpx rgba(255, 107, 138, 0.2);
}

.app-name {
  display: block;
  font-size: 56rpx;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 16rpx;
  letter-spacing: 4rpx;
}

.app-slogan {
  display: block;
  font-size: 28rpx;
  color: var(--text-light);
  line-height: 1.5;
}

/* 登录表单区域 */
.login-form {
  position: relative;
  z-index: 1;
  padding: 0 32rpx;
  animation: slideUp 0.8s ease-out 0.2s both;
}

.login-method {
  background-color: var(--white);
  border-radius: 24rpx;
  padding: 48rpx 32rpx;
  box-shadow: 0 8rpx 32rpx rgba(0, 0, 0, 0.08);
  margin-bottom: 32rpx;
}

/* 输入框组 */
.input-group {
  margin-bottom: 32rpx;
}

.input-group:last-child {
  margin-bottom: 0;
}

.input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  background-color: var(--bg-color);
  border-radius: 16rpx;
  padding: 24rpx;
  border: 2rpx solid transparent;
  transition: all 0.3s ease;
}

.input-wrapper:focus-within {
  border-color: var(--primary-color);
  background-color: var(--white);
  box-shadow: 0 0 0 4rpx rgba(255, 107, 138, 0.1);
}

.input-icon {
  margin-right: 16rpx;
  opacity: 0.6;
}

.phone-input,
.code-input {
  flex: 1;
  font-size: 28rpx;
  color: var(--text-color);
  background: transparent;
  border: none;
  outline: none;
}

.send-code-btn {
  padding: 12rpx 24rpx;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  font-size: 24rpx;
  border: none;
  border-radius: 12rpx;
  transition: all 0.3s ease;
}

.send-code-btn.disabled {
  background: var(--border-color);
  color: var(--text-lighter);
}

/* 登录按钮 */
.login-btn {
  width: 100%;
  height: 88rpx;
  background: var(--border-color);
  color: var(--text-lighter);
  font-size: 32rpx;
  font-weight: 600;
  border: none;
  border-radius: 44rpx;
  transition: all 0.3s ease;
}

.login-btn.active {
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  box-shadow: 0 8rpx 24rpx rgba(255, 107, 138, 0.3);
}

.login-btn:active {
  transform: scale(0.98);
}

/* 微信登录按钮 */
.wechat-login-btn {
  width: 100%;
  height: 88rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16rpx;
  background: linear-gradient(135deg, #07C160, #38CA73);
  color: var(--white);
  font-size: 32rpx;
  font-weight: 600;
  border: none;
  border-radius: 44rpx;
  margin-bottom: 24rpx;
  box-shadow: 0 8rpx 24rpx rgba(7, 193, 96, 0.3);
  transition: all 0.3s ease;
}

.wechat-login-btn.secondary {
  background: var(--white);
  color: #07C160;
  border: 2rpx solid #07C160;
  box-shadow: 0 4rpx 16rpx rgba(7, 193, 96, 0.1);
}

.wechat-login-btn:active {
  transform: scale(0.98);
}

.wechat-icon {
  width: 40rpx;
  height: 40rpx;
}

/* 登录方式切换 */
.login-switch {
  text-align: center;
  margin: 32rpx 0;
}

.switch-text {
  font-size: 28rpx;
  color: var(--primary-color);
  text-decoration: underline;
  cursor: pointer;
}

/* 第三方登录 */
.third-party-login {
  margin-top: 40rpx;
}

.divider-line {
  position: relative;
  text-align: center;
  margin-bottom: 32rpx;
}

.divider-line::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 1rpx;
  background-color: var(--border-color);
}

.divider-text {
  display: inline-block;
  padding: 0 24rpx;
  background-color: var(--bg-color);
  font-size: 24rpx;
  color: var(--text-lighter);
  position: relative;
  z-index: 1;
}

.third-party-buttons {
  display: flex;
  justify-content: center;
  gap: 32rpx;
}

.third-party-btn {
  width: 80rpx;
  height: 80rpx;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  transition: all 0.3s ease;
}

.third-party-btn.apple {
  background-color: #000000;
}

.third-party-btn.qq {
  background-color: #12B7F5;
}

.third-party-btn.weibo {
  background-color: #E6162D;
}

.third-party-btn:active {
  transform: scale(0.95);
}

/* 服务条款区域 */
.terms-section {
  position: relative;
  z-index: 1;
  padding: 32rpx;
  animation: slideUp 0.8s ease-out 0.4s both;
}

.agreement-check {
  display: flex;
  align-items: flex-start;
  gap: 16rpx;
  margin-bottom: 16rpx;
}

.agreement-checkbox {
  margin-top: 4rpx;
  transform: scale(0.8);
}

.agreement-text {
  flex: 1;
  font-size: 24rpx;
  color: var(--text-light);
  line-height: 1.5;
}

.link {
  color: var(--primary-color);
  text-decoration: underline;
}

.safety-tips {
  display: flex;
  align-items: center;
  gap: 8rpx;
  justify-content: center;
}

.tips-text {
  font-size: 22rpx;
  color: var(--text-lighter);
}

/* 登录引导 */
.login-guide {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.8);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32rpx;
}

.guide-content {
  background-color: var(--white);
  border-radius: 24rpx;
  padding: 48rpx 32rpx 32rpx;
  text-align: center;
  max-width: 500rpx;
  width: 100%;
  animation: bounceIn 0.6s ease-out;
}

.guide-image {
  width: 200rpx;
  height: 200rpx;
  margin-bottom: 32rpx;
}

.guide-title {
  display: block;
  font-size: 40rpx;
  font-weight: 600;
  color: var(--text-color);
  margin-bottom: 16rpx;
}

.guide-desc {
  display: block;
  font-size: 28rpx;
  color: var(--text-light);
  margin-bottom: 32rpx;
  line-height: 1.5;
}

.guide-features {
  display: flex;
  flex-direction: column;
  gap: 16rpx;
  margin-bottom: 40rpx;
}

.feature-item {
  display: flex;
  align-items: center;
  gap: 12rpx;
  font-size: 26rpx;
  color: var(--text-color);
}

.guide-close-btn {
  width: 100%;
  height: 88rpx;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: var(--white);
  font-size: 32rpx;
  font-weight: 600;
  border: none;
  border-radius: 44rpx;
  box-shadow: 0 8rpx 24rpx rgba(255, 107, 138, 0.3);
}

/* 协议弹窗 */
.agreement-modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  z-index: 9998;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32rpx;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
}

.agreement-modal.show {
  opacity: 1;
  visibility: visible;
}

.modal-content {
  background-color: var(--white);
  border-radius: 24rpx;
  max-width: 600rpx;
  width: 100%;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  transform: scale(0.9);
  transition: transform 0.3s ease;
}

.agreement-modal.show .modal-content {
  transform: scale(1);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 32rpx;
  border-bottom: 1rpx solid var(--border-color);
}

.modal-title {
  font-size: 32rpx;
  font-weight: 600;
  color: var(--text-color);
}

.close-icon {
  padding: 8rpx;
  color: var(--text-lighter);
}

.modal-body {
  flex: 1;
  padding: 32rpx;
  max-height: 60vh;
}

.agreement-content {
  font-size: 26rpx;
  line-height: 1.6;
  color: var(--text-color);
  white-space: pre-line;
}

.modal-footer {
  padding: 24rpx 32rpx;
  border-top: 1rpx solid var(--border-color);
}

.modal-footer .btn {
  width: 100%;
  height: 80rpx;
  border-radius: 40rpx;
  font-size: 28rpx;
}

/* 动画定义 */
@keyframes float {
  0%, 100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-20px);
  }
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-100rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(100rpx);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes bounceIn {
  0% {
    opacity: 0;
    transform: scale(0.3);
  }
  50% {
    opacity: 1;
    transform: scale(1.05);
  }
  70% {
    transform: scale(0.9);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* 响应式适配 */
@media (max-width: 320px) {
  .header-section {
    padding: 100rpx 24rpx 60rpx;
  }

  .app-logo {
    width: 120rpx;
    height: 120rpx;
  }

  .app-name {
    font-size: 48rpx;
  }

  .login-form {
    padding: 0 24rpx;
  }

  .login-method {
    padding: 40rpx 24rpx;
  }

  .login-btn,
  .wechat-login-btn {
    height: 80rpx;
    font-size: 28rpx;
  }
}

/* 减少动画（针对低性能设备） */
@media (prefers-reduced-motion: reduce) {
  .decoration-circle,
  .header-section,
